/**
 * Format teks nama (cth: bahasa_melayu -> Bahasa Melayu)
 */
function formatLabel(str) {
  if (!str) return "";
  return str
    .split("_")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(" ");
}

/**
 * Penghurai CSV mematuhi piawaian RFC-4180
 * Menyokong koma dalam teks, petikan berganda (""), dan baris baharu (CRLF/LF).
 */
function parseCSV(text) {
  const lines = [];
  let row = [''];
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const next = text[i + 1];

    if (inQuotes) {
      if (c === '"' && next === '"') {
        row[row.length - 1] += '"';
        i++;
      } else if (c === '"') {
        inQuotes = false;
      } else {
        row[row.length - 1] += c;
      }
    } else {
      if (c === '"') {
        inQuotes = true;
      } else if (c === ',') {
        row.push('');
      } else if (c === '\r' && next === '\n') {
        lines.push(row);
        row = [''];
        i++;
      } else if (c === '\n' || c === '\r') {
        lines.push(row);
        row = [''];
      } else {
        row[row.length - 1] += c;
      }
    }
  }
  if (row.length > 1 || (row.length === 1 && row[0] !== '')) {
    lines.push(row);
  }
  return lines;
}

/**
 * Membina struktur bab dan topik daripada teks CSV
 */
function buildChaptersFromCSV(csvText) {
  const parsedRows = parseCSV(csvText);
  if (!parsedRows || parsedRows.length < 2) {
    throw new Error("Fail CSV kosong atau format tidak sah.");
  }

  const headers = parsedRows[0].map((h) => h.trim().toLowerCase());
  const colMap = {};
  headers.forEach((h, i) => { colMap[h] = i; });

  const getCol = (row, colName) => {
    const idx = colMap[colName];
    return (idx !== undefined && row[idx] !== undefined) ? row[idx].trim() : '';
  };

  const chapters = [];
  const chapterMap = new Map();
  const topicMap = new Map();

  for (let r = 1; r < parsedRows.length; r++) {
    const row = parsedRows[r];
    if (!row || row.length === 0 || (row.length === 1 && row[0] === '')) continue;

    const chapterName = getCol(row, 'chapter');
    if (!chapterName) continue;

    const chapterId = getCol(row, 'chapter_id') || chapterName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    const topicName = getCol(row, 'topic') || 'Topik Umum';
    const topicId = getCol(row, 'topic_id') || topicName.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    const type = getCol(row, 'type').toLowerCase();
    const text = getCol(row, 'text');
    const textEn = getCol(row, 'text_en');
    const choiceA = getCol(row, 'choice_a');
    const choiceB = getCol(row, 'choice_b');
    const choiceC = getCol(row, 'choice_c');
    const choiceD = getCol(row, 'choice_d');
    const answer = getCol(row, 'answer');
    const personName = getCol(row, 'person_name');
    const personRole = getCol(row, 'person_role');

    let chapter = chapterMap.get(chapterId);
    if (!chapter) {
      chapter = { id: chapterId, name: chapterName, topics: [] };
      chapterMap.set(chapterId, chapter);
      chapters.push(chapter);
    }

    const topicKey = `${chapterId}:::${topicId}`;
    let topic = topicMap.get(topicKey);
    if (!topic) {
      topic = {
        id: topicId,
        name: topicName,
        summary: '',
        summary_en: '',
        facts: [],
        facts_en: [],
        persons: [],
        quiz: []
      };
      topicMap.set(topicKey, topic);
      chapter.topics.push(topic);
    }

    if (type === 'summary') {
      topic.summary = text;
      topic.summary_en = textEn;
    } else if (type === 'fact') {
      if (text) {
        topic.facts.push(text);
        if (textEn) topic.facts_en.push(textEn);
      }
    } else if (type === 'person') {
      if (personName || text) {
        topic.persons.push({
          name: personName,
          role: personRole,
          description: text,
          description_en: textEn
        });
      }
    } else if (type === 'multiple_choice' || type === 'objective' || type === 'quiz') {
      const choices = [choiceA, choiceB, choiceC, choiceD].filter(Boolean);
      const quizItem = {
        question: text,
        answer: answer
      };
      if (type === 'objective') {
        quizItem.type = 'objective';
      }
      if (choices.length > 0) {
        quizItem.choices = choices;
      }
      topic.quiz.push(quizItem);
    }
  }

  return chapters;
}

/**
 * Papar status atau mesej panduan
 */
function showStatus(message, type = "info") {
  if (!message) {
    statusMessageEl.style.display = "none";
    statusMessageEl.innerHTML = "";
    statusMessageEl.className = "status-message";
    return;
  }
  statusMessageEl.className = `status-message ${type}`;
  statusMessageEl.innerHTML = message;
  statusMessageEl.style.display = "block";
}

/**
 * Memuatkan fail index.json untuk menyenaraikan CSV yang tersedia
 */
async function loadAvailableDatasets() {
  try {
    const res = await fetch("data/index.json");
    if (!res.ok) throw new Error("Gagal mengambil data/index.json");
    const data = await res.json();
    if (Array.isArray(data) && data.length > 0) {
      availableDatasets = data
        .filter((d) => {
          const fileName = (typeof d === "string" ? d : d.file || d.fileName || "").toLowerCase();
          return !fileName.includes("template");
        })
        .map((d) => {
          if (typeof d === "string") {
            const fileName = d.replace(/^data[\/\\]/, '');
            const match = fileName.match(/^(.*)_(tingkatan_\d+)(?:_.*)?\.csv$/i);
            const subjectId = match ? match[1].toLowerCase() : fileName.replace(/\.csv$/i, '').toLowerCase();
            const tingkatanId = match ? match[2].toLowerCase() : "tingkatan_1";
            return {
              file: `data/${fileName}`,
              fileName: fileName,
              subjectId: subjectId,
              subjectName: formatLabel(subjectId),
              tingkatanId: tingkatanId,
              tingkatanName: formatLabel(tingkatanId)
            };
          }
          return {
            file: d.file,
            fileName: d.fileName || d.file.split('/').pop(),
            subjectId: d.subjectId,
            subjectName: d.subjectName || formatLabel(d.subjectId),
            tingkatanId: d.tingkatanId,
            tingkatanName: d.tingkatanName || formatLabel(d.tingkatanId)
          };
        });
    } else {
      availableDatasets = DEFAULT_DATASETS.filter((dataset) => EMBEDDED_FALLBACKS[dataset.file]);
    }
  } catch (err) {
    console.warn("Menggunakan senarai dataset sandaran:", err);
    availableDatasets = DEFAULT_DATASETS.filter((dataset) => EMBEDDED_FALLBACKS[dataset.file]);
  }

  populateTingkatanDropdown();
}

/**
 * Penuhkan dropdown Tingkatan mengikut CSV yang wujud
 */
function populateTingkatanDropdown() {
  tingkatanSelect.innerHTML = "";

  const uniqueTingkatans = [];
  const seen = new Set();

  availableDatasets.forEach((d) => {
    if (!seen.has(d.tingkatanId)) {
      seen.add(d.tingkatanId);
      uniqueTingkatans.push({ id: d.tingkatanId, name: d.tingkatanName });
    }
  });

  if (uniqueTingkatans.length === 0) {
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = "-- Tiada Fail CSV Dijumpai --";
    placeholder.disabled = true;
    placeholder.selected = true;
    tingkatanSelect.appendChild(placeholder);
    populateSubjectDropdown();
    return;
  }

  uniqueTingkatans.forEach((t) => {
    const opt = document.createElement("option");
    opt.value = t.id;
    opt.textContent = t.name;
    tingkatanSelect.appendChild(opt);
  });

  tingkatanSelect.value = uniqueTingkatans[0].id;
  populateSubjectDropdown();
}

/**
 * Penuhkan dropdown Subjek mengikut Tingkatan yang dipilih
 */
function populateSubjectDropdown() {
  subjectSelect.innerHTML = "";

  const selectedTingkatan = tingkatanSelect.value;
  const filtered = availableDatasets.filter((d) => d.tingkatanId === selectedTingkatan);

  if (filtered.length === 0) {
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = "-- Tiada Subjek --";
    placeholder.disabled = true;
    placeholder.selected = true;
    subjectSelect.appendChild(placeholder);
    loadSelectedDataset();
    return;
  }

  filtered.forEach((d) => {
    const opt = document.createElement("option");
    opt.value = d.subjectId;
    opt.textContent = d.subjectName;
    subjectSelect.appendChild(opt);
  });

  subjectSelect.value = filtered[0].subjectId;
  loadSelectedDataset();
}

/**
 * Muat data CSV bagi kombinasi Tingkatan dan Subjek yang dipilih
 */
async function loadSelectedDataset() {
  const tingkatanId = tingkatanSelect.value;
  const subjectId = subjectSelect.value;

  const dataset = availableDatasets.find(
    (d) => d.tingkatanId === tingkatanId && d.subjectId === subjectId
  );

  if (!dataset) {
    showStatus("Tiada fail CSV ditemui untuk pilihan ini.", "warning");
    currentChapters = [];
    chapterSelect.innerHTML = "<option value=''>-- Tiada Bab --</option>";
    topicSelect.innerHTML = "<option value=''>-- Tiada Topik --</option>";
    resultEl.innerHTML = "";
    return;
  }

  currentDatasetInfo = {
    subject: dataset.subjectName,
    tingkatan: dataset.tingkatanName
  };

  showStatus(`Memuatkan fail ${dataset.fileName}...`, "info");

  try {
    const response = await fetch(dataset.file);
    if (!response.ok) {
      throw new Error(`Fail ${dataset.file} tidak dapat dimuat (Status ${response.status})`);
    }
    const csvText = await response.text();
    loadCSVData(csvText);
    showStatus("");
  } catch (err) {
    console.warn("Fetch gagal:", err);

    // Semak jika ada sandaran terbina bagi fail ini
    if (EMBEDDED_FALLBACKS[dataset.file]) {
      console.info("Menggunakan data sandaran terbina untuk:", dataset.file);
      loadCSVData(EMBEDDED_FALLBACKS[dataset.file]);
      showStatus("");
      return;
    }

    showStatus(`Gagal memuatkan fail ${dataset.file}: ${err.message}`, "error");
  }
}

/**
 * Muat dan pasang data CSV daripada teks
 */
function loadCSVData(csvText) {
  try {
    const chapters = buildChaptersFromCSV(csvText);
    if (!chapters || chapters.length === 0) {
      throw new Error("Tiada bab dijumpai dalam fail CSV ini.");
    }

    currentChapters = chapters;
    populateChapters();
    populateTopics();
    generate();
  } catch (err) {
    console.error("Ralat memproses CSV:", err);
    currentChapters = [];
    chapterSelect.innerHTML = "<option value=''>-- Tiada Bab --</option>";
    topicSelect.innerHTML = "<option value=''>-- Tiada Topik --</option>";
    resultEl.innerHTML = "";
    showStatus(`<strong>Ralat Format CSV:</strong> ${err.message}`, "error");
  }
}

/**
 * Penuhkan pilihan Bab
 */
function populateChapters() {
  chapterSelect.innerHTML = "";

  if (currentChapters.length === 0) {
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = "-- Tiada Bab --";
    placeholder.disabled = true;
    placeholder.selected = true;
    chapterSelect.appendChild(placeholder);
    return;
  }

  currentChapters.forEach((chapter) => {
    const option = document.createElement("option");
    option.value = chapter.id;
    option.textContent = chapter.name;
    chapterSelect.appendChild(option);
  });

  chapterSelect.value = currentChapters[0].id;
}

function getSelectedChapter() {
  return currentChapters.find((chapter) => chapter.id === chapterSelect.value) || currentChapters[0];
}

/**
 * Penuhkan pilihan Topik
 */
function populateTopics() {
  const chapter = getSelectedChapter();
  topicSelect.innerHTML = "";

  if (!chapter || !chapter.topics || chapter.topics.length === 0) {
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = "-- Tiada Topik --";
    placeholder.disabled = true;
    placeholder.selected = true;
    topicSelect.appendChild(placeholder);
    return;
  }

  chapter.topics.forEach((topic) => {
    const option = document.createElement("option");
    option.value = topic.id;
    option.textContent = topic.name;
    topicSelect.appendChild(option);
  });

  topicSelect.value = chapter.topics[0].id;
}

function getSelectedTopic() {
  const chapter = getSelectedChapter();
  if (!chapter || !chapter.topics) {
    return null;
  }
  return chapter.topics.find((topic) => topic.id === topicSelect.value) || chapter.topics[0];
}

function updateQuickNav() {
  if (!quickNav) return;

  const chapterIndex = currentChapters.findIndex((chapter) => chapter.id === chapterSelect.value);
  const chapter = getSelectedChapter();
  const topicIndex = chapter ? chapter.topics.findIndex((topic) => topic.id === topicSelect.value) : -1;
  const previousChapterLink = quickNav.querySelector('[data-quick-action="previous-chapter"]');
  const nextChapterLink = quickNav.querySelector('[data-quick-action="next-chapter"]');
  const previousSectionLink = quickNav.querySelector('[data-quick-action="previous-section"]');
  const nextSectionLink = quickNav.querySelector('[data-quick-action="next-section"]');

  const setDisabled = (link, disabled) => {
    link.classList.toggle("is-disabled", disabled);
    link.setAttribute("aria-disabled", String(disabled));
    if (disabled) {
      link.setAttribute("tabindex", "-1");
    } else {
      link.removeAttribute("tabindex");
    }
  };

  setDisabled(previousChapterLink, chapterIndex <= 0);
  setDisabled(nextChapterLink, chapterIndex < 0 || chapterIndex >= currentChapters.length - 1);
  setDisabled(previousSectionLink, !chapter || topicIndex <= 0);
  setDisabled(nextSectionLink, !chapter || topicIndex < 0 || topicIndex >= chapter.topics.length - 1);
}

/**
 * Lencana maklumat subjek & tingkatan semasa
 */
function getDatasetBadgeHtml() {
  if (!currentDatasetInfo.subject && !currentDatasetInfo.tingkatan) return "";
  return `<div class="dataset-badge">📖 ${currentDatasetInfo.subject} &bull; ${currentDatasetInfo.tingkatan}</div>`;
}

function englishOnly(text) {
  if (!text) return "";
  const bilingualParts = text.split(/\s(?:\/|\|)\s/);
  const englishText = bilingualParts.length > 1
    ? bilingualParts
      .filter((part, index) => index % 2 === 1 && !/^(jawapan|cara|oleh itu|kaedah|soalan)$/i.test(part.trim()))
      .join(" / ")
      .trim()
    : text;
  return englishText
    .replace(/\b(?:Cara|Oleh itu|Jawapan|Soalan|Kaedah)\s*\/\s*/gi, "")
    .replace(/\s+\b(?:Oleh itu|Cara|Jawapan|Soalan|Kaedah)\s*$/i, "")
    .trim();
}

function englishLabel(text) {
  return /\s(?:\/|\|)\s/.test(text) ? englishOnly(text) : "";
}

function malayOnly(text) {
  if (!text) return "";
  const bilingualParts = text.split(/\s(?:\/|\|)\s/);
  return bilingualParts.length > 1
    ? bilingualParts.filter((_, index) => index % 2 === 0).join(" ").trim()
    : text;
}

async function translateToChinese(text) {
  const response = await fetch(`https://translate.googleapis.com/translate_a/single?client=gtx&sl=ms&tl=zh-CN&dt=t&q=${encodeURIComponent(text)}`);
  if (!response.ok) throw new Error("Perkhidmatan terjemahan tidak tersedia.");
  const data = await response.json();
  return Array.isArray(data[0]) ? data[0].map((part) => part[0]).join("") : text;
}

function markForTranslation(text) {
  return `<span data-translate="${encodeURIComponent(text)}">${text}</span>`;
}

function markMalayAndChinese(text) {
  return `<span class="translation-pair"><span>${text}</span><span class="translation-zh" data-translate="${encodeURIComponent(text)}"></span></span>`;
}

async function translateRenderedOutput() {
  const elements = [...resultEl.querySelectorAll("[data-translate]")];
  const uniqueTexts = [...new Set(elements.map((element) => decodeURIComponent(element.dataset.translate)))];
  const translations = await Promise.all(uniqueTexts.map(async (text) => [text, await translateToChinese(text)]));
  const translationMap = new Map(translations);
  elements.forEach((element) => {
    element.textContent = translationMap.get(decodeURIComponent(element.dataset.translate)) || element.textContent;
  });
}

/**
 * Paparan Fakta Penting & Ringkasan
 */
function renderFacts(topic) {
  const summaryHtml = topic.summary
    ? `<div class="topic-summary">
         <p><strong>Ringkasan Topik:</strong> ${topic.summary}</p>
         ${topic.summary_en ? `<p class="summary-en">${topic.summary_en}</p>` : ""}
       </div>`
    : "";

  const listItems = (topic.facts || [])
    .map((fact, index) => {
      const englishFact = topic.facts_en && topic.facts_en[index]
        ? ` <span class="fact-en">/ ${topic.facts_en[index]}</span>`
        : "";
      return `<li>${fact}${englishFact}</li>`;
    })
    .join("");

  const personsHtml = (topic.persons && topic.persons.length > 0)
    ? topic.persons
        .map(
          (person) => `
            <article class="person-item">
              <p><strong>${person.name}</strong> ${person.role ? `— <em>${person.role}</em>` : ""}</p>
              ${person.description ? `<p>${person.description}</p>` : ""}
              ${person.description_en ? `<p class="person-en">${person.description_en}</p>` : ""}
            </article>`
        )
        .join("")
    : "";

  const personsSection = personsHtml
    ? `<div class="important-people">
         <h4>Tokoh Penting (Malay) / Important People (English):</h4>
         ${personsHtml}
       </div>`
    : "";

  return `
    ${getDatasetBadgeHtml()}
    <h2 class="topic-title">${topic.name}</h2>
    ${summaryHtml}
    ${listItems ? `<ul>${listItems}</ul>` : "<p>Tiada senarai fakta.</p>"}
    ${personsSection}
  `;
}

/**
 * Paparan Kuiz
 */
function renderQuiz(topic) {
  if (!topic.quiz || topic.quiz.length === 0) {
    return `${getDatasetBadgeHtml()}<h2 class="topic-title">${topic.name}</h2><p>Tiada soalan kuiz untuk topik ini.</p>`;
  }

  const questionHtml = topic.quiz
    .map((item, index) => {
      const hasChoices = item.choices && item.choices.length > 0;
      const choicesHtml = hasChoices
        ? item.choices
            .map(
              (choice, choiceIndex) =>
                `<li><strong>${String.fromCharCode(65 + choiceIndex)}.</strong> ${choice}</li>`
            )
            .join("")
        : "";

      return `
        <article class="quiz-item">
          <h3>Soalan ${index + 1} / Question ${index + 1}</h3>
          <p><strong>${item.question}</strong></p>
          ${hasChoices ? `<ul>${choicesHtml}</ul>` : ""}
          <div class="quiz-answer">
            <strong>Jawapan / Answer:</strong> ${item.answer}
          </div>
        </article>`;
    })
    .join("");

  return `${getDatasetBadgeHtml()}<h2 class="topic-title">${topic.name}</h2>${questionHtml}`;
}

function renderMalayChinese(topic) {
  const facts = (topic.facts || [])
    .map((fact) => `<li>${markMalayAndChinese(malayOnly(fact))}</li>`)
    .join("");
  const quizItems = (topic.quiz || []).map((item, index) => {
    const choicesHtml = (item.choices || [])
      .map((choice, choiceIndex) => `<li><strong>${String.fromCharCode(65 + choiceIndex)}.</strong> ${markMalayAndChinese(malayOnly(choice))}</li>`)
      .join("");
    return `<article class="quiz-item">
      <h3>Soalan ${index + 1}</h3>
      <p><strong>${markMalayAndChinese(malayOnly(item.question))}</strong></p>
      ${choicesHtml ? `<ul>${choicesHtml}</ul>` : ""}
      <div class="quiz-answer"><strong>Jawapan:</strong> ${markMalayAndChinese(malayOnly(item.answer))}</div>
    </article>`;
  }).join("");

  return `${getDatasetBadgeHtml()}<h2 class="topic-title">${markMalayAndChinese(malayOnly(topic.name))}</h2>
    ${topic.summary ? `<div class="topic-summary"><p><strong>Ringkasan Topik:</strong> ${markMalayAndChinese(malayOnly(topic.summary))}</p></div>` : ""}
    ${facts ? `<ul>${facts}</ul>` : ""}
    ${quizItems}`;
}

/**
 * Hasilkan paparan berasaskan mod yang dipilih
 */
async function generate() {
  const topic = getSelectedTopic();
  const language = currentLanguage;
  const mode = modeSelect.value;

  if (!topic) {
    resultEl.innerHTML = "<p>Sila pilih bab dan topik yang sah.</p>";
    return;
  }

  let output = "";
  if (language === "ms-zh") {
    output = renderMalayChinese({ ...topic, quiz: mode === "quiz" ? topic.quiz : [] });
  } else if (mode === "summary-facts") {
    output = renderFacts(topic);
  } else if (mode === "quiz") {
    output = renderQuiz(topic);
  }

  resultEl.innerHTML = output;
  updateQuickNav();

  if (language === "ms-zh") {
    try {
      await translateRenderedOutput();
    } catch (error) {
      showStatus(`Terjemahan Cina gagal: ${error.message}`, "warning");
    }
  }
}

quickNav?.addEventListener("click", (event) => {
  const link = event.target.closest("a[data-quick-action]");
  if (!link || link.getAttribute("aria-disabled") === "true") {
    event.preventDefault();
    return;
  }

  const action = link.dataset.quickAction;
  if (action === "top") return;

  event.preventDefault();

  if (action === "facts") {
    modeSelect.value = "summary-facts";
    generate();
  } else if (action === "quiz") {
    modeSelect.value = "quiz";
    generate();
  } else if (action === "previous-chapter" || action === "next-chapter") {
    const chapterIndex = currentChapters.findIndex((chapter) => chapter.id === chapterSelect.value);
    const chapterOffset = action === "previous-chapter" ? -1 : 1;
    const targetChapter = currentChapters[chapterIndex + chapterOffset];
    if (targetChapter) {
      chapterSelect.value = targetChapter.id;
      populateTopics();
      generate();
    }
  } else if (action === "previous-section" || action === "next-section") {
    const chapter = getSelectedChapter();
    const topicIndex = chapter ? chapter.topics.findIndex((topic) => topic.id === topicSelect.value) : -1;
    const topicOffset = action === "previous-section" ? -1 : 1;
    const targetTopic = chapter?.topics[topicIndex + topicOffset];
    if (targetTopic) {
      topicSelect.value = targetTopic.id;
      generate();
    }
  }

  resultEl.scrollIntoView({ behavior: "smooth", block: "start" });
});

// Pasang event listeners
tingkatanSelect.addEventListener("change", () => {
  populateSubjectDropdown();
});
subjectSelect.addEventListener("change", () => {
  loadSelectedDataset();
});
chapterSelect.addEventListener("change", () => {
  populateTopics();
  generate();
});
topicSelect.addEventListener("change", generate);
languageButtons.forEach((button) => {
  button.addEventListener("click", () => {
    currentLanguage = button.dataset.language;
    languageButtons.forEach((languageButton) => {
      const isActive = languageButton === button;
      languageButton.classList.toggle("is-active", isActive);
      languageButton.setAttribute("aria-pressed", String(isActive));
    });
    generate();
  });
});
modeSelect.addEventListener("change", generate);
generateBtn.addEventListener("click", generate);

// Mulakan aplikasi
loadAvailableDatasets();
